<script lang="ts">
  import { onDestroy } from 'svelte';
  type ClickPoint={x:number;y:number;rage:boolean;dead:boolean;target:string;label:string;href:string;sessionId:string;vw:number;vh:number;device:string};
  type PageRow={path:string;clicks:ClickPoint[];scrolls:number[];totalClicks:number;rageClicks:number;deadClicks:number;sessions:number;exits:number;exitRate:number;avgActiveMs:number;avgVisibleMs:number;avgScroll:number;maxScroll:number;targets:{target:string;label:string;href:string;clicks:number;rage:number;dead:number}[];irritations:{target:string;label:string;href:string;clicks:number;rage:number;dead:number}[];exitInteractions:{label:string;count:number}[];atc:number;checkout:number;checkoutFromAtc:number;diagnosis:string;funnelSignal:string;defaultDevice:string;snapshotWidth:number;snapshotHeight:number;devices:{device:string;sessions:number}[]};
  export let data:{pages:PageRow[];period:{range:string;label:string};totals:{sessions:number;avgActiveMs:number;topExitPath:string;topExitCount:number}};
  let selected=data.pages[0]?.path||'';let frame:HTMLIFrameElement|null=null;let resizeObserver:ResizeObserver|null=null;let timers:number[]=[];let stageHeight=900;let snapshotNonce=0;
  $: page=data.pages.find(p=>p.path===selected)||data.pages[0];
  $: liveUrl=page?`https://trendypatike.com${page.path}`:'https://trendypatike.com';
  $: snapshotSrc=page?`/heatmaps/snapshot?path=${encodeURIComponent(page.path)}&r=${snapshotNonce}`:'';
  $: sameLayoutClicks=page?page.clicks.filter(p=>p.device===page.defaultDevice||p.device==='unknown'):[];
  $: plottedClicks=sameLayoutClicks.length?sameLayoutClicks:(page?.clicks||[]);
  $: hiddenSignals=page?Math.max(0,page.clicks.length-plottedClicks.length):0;
  $: if(page)stageHeight=Math.max(650,Math.min(1600,page.snapshotHeight*1.2));
  const dur=(ms:number)=>{const s=Math.round(ms/1000);return s<60?`${s}s`:`${Math.floor(s/60)}m ${s%60}s`;};
  const href=(range:string)=>`/heatmaps?range=${range}`;
  function clearFrameWatchers(){resizeObserver?.disconnect();resizeObserver=null;for(const id of timers)window.clearTimeout(id);timers=[];}
  function syncFrameHeight(){try{const doc=frame?.contentDocument;if(!doc)return;const h=Math.max(doc.documentElement?.scrollHeight||0,doc.body?.scrollHeight||0,page?.snapshotHeight||650);if(h>0)stageHeight=Math.max(650,Math.min(24000,h));}catch{}}
  function frameLoaded(){clearFrameWatchers();syncFrameHeight();timers.push(window.setTimeout(syncFrameHeight,350));timers.push(window.setTimeout(syncFrameHeight,1200));try{const root=frame?.contentDocument?.documentElement;if(root&&typeof ResizeObserver!=='undefined'){resizeObserver=new ResizeObserver(syncFrameHeight);resizeObserver.observe(root);}}catch{}}
  function refreshSnapshot(){clearFrameWatchers();snapshotNonce+=1;}onDestroy(clearFrameWatchers);
</script>

<header><div class="eyebrow">PONAŠANJE KUPACA · {data.period.label.toUpperCase()}</div><h1>Šta kupci rade i gde odustaju</h1><p>Ne samo procenat: vidi šta klikću, šta ih frustrira, koliko daleko stižu i na kom koraku se gubi namera za kupovinu.</p></header>
<nav class="periods" aria-label="Period analize"><a class:active={data.period.range==='today'} href={href('today')}>Danas</a><a class:active={data.period.range==='yesterday'} href={href('yesterday')}>Juče</a><a class:active={data.period.range==='7d'} href={href('7d')}>7 dana</a><a class:active={data.period.range==='30d'} href={href('30d')}>30 dana</a></nav>
<section class="summary"><div><span>Sesije</span><b>{data.totals.sessions}</b><small>{data.period.label}</small></div><div><span>Najčešći izlaz</span><b class="path">{data.totals.topExitPath||'—'}</b><small>{data.totals.topExitCount} sesija je završilo tu</small></div><div><span>Prosečno trajanje</span><b>{dur(data.totals.avgActiveMs)}</b><small>od ulaska do poslednjeg signala</small></div></section>

{#if data.pages.length}
<section class="controls"><label for="heatmap-page">Analiziraj stranicu</label><select id="heatmap-page" bind:value={selected}>{#each data.pages as p}<option value={p.path}>{p.path} · {p.sessions} poseta · {p.exits} izlaza</option>{/each}</select><button type="button" class="refresh" on:click={refreshSnapshot}>Osveži prikaz</button><a class="open" href={liveUrl} target="_blank" rel="noreferrer">Otvori original ↗</a></section>
{#if page}
<section class="diagnostics">
  <article class="primary"><span>GLAVNI SIGNAL</span><h2>{page.diagnosis}</h2><p>Ovo je zaključak iz ponašanja u izabranom periodu, ne pretpostavka o motivu kupca.</p></article>
  <article><span>POSLE DODAVANJA U KORPU</span><h2>{page.funnelSignal}</h2><p>{page.atc>0&&page.checkoutFromAtc<40?'Ovde vredi prvo proveriti cenu, dostavu, izbor veličine i jasnoću checkout CTA-a.':'Nema jakog pada između korpe i checkout signala na ovoj stranici.'}</p></article>
  <article><span>NAJVEĆA IRITACIJA</span><h2>{page.irritations[0]?(page.irritations[0].label||page.irritations[0].target||'Nepoznat element'):'Nema rage/dead signala'}</h2><p>{page.irritations[0]?`${page.irritations[0].rage} rage · ${page.irritations[0].dead} dead klikova. Ovo je prvi element za proveru.`:'Nismo zabeležili ponovljene ili “mrtve” klikove u ovom periodu.'}</p></article>
  <article><span>NAJČEŠĆE PRE IZLASKA</span><h2>{page.exitInteractions[0]?.label||'Nema jasne poslednje interakcije'}</h2><p>{page.exitInteractions[0]?`${page.exitInteractions[0].count} izlaza desilo se nakon ove poslednje interakcije.`:'Kupci uglavnom izlaze bez dovoljno jasnog poslednjeg klika za zaključak.'}</p></article>
</section>
<section class="metrics"><div><span>Posete</span><b>{page.sessions}</b></div><div><span>Završile ovde</span><b>{page.exits} · {page.exitRate.toFixed(1)}%</b></div><div><span>Aktivno vreme</span><b>{dur(page.avgActiveMs)}</b></div><div><span>Prosečan scroll</span><b>{page.avgScroll.toFixed(0)}%</b></div><div><span>Add to cart</span><b>{page.atc}</b></div><div><span>Checkout signal</span><b>{page.checkout}</b></div></section>
<div class="truth"><b>Važno:</b> možemo pouzdano reći <i>šta se desilo pre izlaska</i>, ali ne možemo tvrditi psihološki razlog kupca bez dodatnog signala. Za Shopify hosted checkout trenutno vidimo ulazak/namjeru ka checkoutu, ne sadržaj privatnih formi ili payment greške.</div>

<div class="grid"><section class="panel snapshot-panel"><div class="head"><div><div class="eyebrow">STRANICA + STVARNI KLIKOVI</div><h2>{page.path}</h2><small>{page.defaultDevice} · približno {page.snapshotWidth}×{page.snapshotHeight}px</small></div><small>{plottedClicks.length} prikazanih klikova{hiddenSignals?` · ${hiddenSignals} sa drugih uređaja sakriveno`:''}</small></div><div class="snapshot-scroll"><div class="snapshot-stage" style={`width:${page.snapshotWidth}px;height:${stageHeight}px;`}><iframe bind:this={frame} src={snapshotSrc} title={`Storefront snapshot ${page.path}`} scrolling="no" on:load={frameLoaded}></iframe><div class="overlay">{#each plottedClicks as point}<span class:rage={point.rage} class:dead={point.dead} title={`${point.label||point.target||'klik'}${point.href?` → ${point.href}`:''}`} style={`left:${point.x}%;top:${point.y}%;`}></span>{/each}</div></div></div></section>
<section class="panel side"><div class="eyebrow">DOKLE STIGNU</div><h2>Scroll po posetama</h2>{#each [25,50,75,90,100] as mark}{@const count=page.scrolls.filter(d=>d>=mark).length}<div class="scroll-row"><span>{mark}%</span><div><i style={`width:${page.scrolls.length?Math.min(100,count/page.scrolls.length*100):0}%`}></i></div><b>{page.scrolls.length?`${Math.round(count/page.scrolls.length*100)}%`:'—'}</b><small>{count} ses.</small></div>{/each}<div class="note">Ako veliki deo kupaca ne stigne do dela stranice gde su cena, veličina, dostava ili CTA, problem može biti u rasporedu sadržaja pre tog mesta.</div></section></div>

<section class="two"><section class="panel"><div class="eyebrow">ŠTA NAJVIŠE RADE</div><h2>Najčešće akcije</h2>{#if page.targets.length}<div class="table-wrap"><table><thead><tr><th>Element</th><th>Klikovi</th><th>Rage</th><th>Dead</th></tr></thead><tbody>{#each page.targets.slice(0,12) as t}<tr><td><strong>{t.label||t.target||'—'}</strong><small>{t.href||t.target||''}</small></td><td>{t.clicks}</td><td class:bad={t.rage>0}>{t.rage}</td><td class:bad={t.dead>0}>{t.dead}</td></tr>{/each}</tbody></table></div>{:else}<div class="empty">Nema click signala.</div>{/if}</section>
<section class="panel"><div class="eyebrow">ŠTA SE DESI PRE IZLASKA</div><h2>Poslednja interakcija</h2>{#if page.exitInteractions.length}<div class="exit-list">{#each page.exitInteractions as e}<div><strong>{e.label}</strong><span>{e.count} izlaza</span></div>{/each}</div>{:else}<div class="empty">Nema dovoljno page-exit signala.</div>{/if}</section></section>
{/if}
{:else}<div class="empty">Nema heatmap podataka za izabrani period.</div>{/if}

