px;line-height:1.5}.grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(280px,.45fr);gap:12px}.panel{padding:20px}.head{display:flex;justify-content:space-between;gap:16px;align-items:end;margin-bottom:14px}.head small{color:#737d8b;font-size:11px}.snapshot-scroll{overflow:auto;max-width:100%;border:1px solid #20262e;border-radius:14px;background:#080a0d}.snapshot-stage{position:relative;background:white;overflow:hidden}.snapshot-stage iframe{position:absolute;inset:0;width:100%;height:100%;border:0;background:white;pointer-events:none}.overlay{position:absolute;inset:0;z-index:4;pointer-events:none}.overlay span{position:absolute;width:20px;height:20px;border-radius:50%;background:rgba(255,174,48,.78);box-shadow:0 0 0 7px rgba(255,174,48,.2);transform:translate(-50%,-50%)}.overlay span.rage{background:rgba(255,74,74,.92);box-shadow:0 0 0 9px rgba(255,74,74,.22)}.overlay span.dead{outline:3px solid #9b72ff;outline-offset:3px}.side h2{margin-bottom:20px}.scroll-row{display:grid;grid-template-columns:38px 1fr 42px 46px;gap:8px;align-items:center;margin:14px 0}.scroll-row div{height:9px;border-radius:99px;background:#20262d;overflow:hidden}.scroll-row i{display:block;height:100%;background:#8bf048;border-radius:99px}.scroll-row small{color:#65707e;font-size:9px}.note{margin-top:22px;padding:13px;background:#111a10;border:1px solid #263720;border-radius:12px;color:#92b484;font-size:11px;line-height:1.5}.two{display:grid;grid-template-columns:1.2fr .8fr;gap:12px;margin-top:12px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:11px;border-bottom:1px solid #1e232a}th{color:#77818f;font-size:10px;text-transform:uppercase}td small{display:block;color:#65707e;margin-top:4px}.bad{color:#ff958b;font-weight:800}.exit-list{display:grid;gap:8px;margin-top:14px}.exit-list div{display:flex;justify-content:space-between;gap:12px;padding:12px;background:#0c0f13;border:1px solid #1c2128;border-radius:11px}.exit-list strong{font-size:12px}.exit-list span{color:#9aa4b1;font-size:11px}.empty{padding:18px;background:#0c0f13;border:1px dashed #2a313a;border-radius:14px;color:#8e98a7}@media(max-width:1100px){.diagnostics{grid-template-columns:repeat(2,1fr)}.grid,.two{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.summary,.diagnostics,.metrics{grid-template-columns:1fr}.controls{display:grid;grid-template-columns:1fr}.controls select{min-width:0;max-width:100%;width:100%}.open,.refresh{width:max-content}.panel{padding:14px}.head{display:grid;align-items:start}}
</style>
